-- codemasterghana — database schema
-- Generated by `npm run db:schema` from src/lib/schema.ts (do not edit by hand).
--
-- Run this once against your database (Supabase SQL editor, psql, Neon console).
-- Every statement is idempotent, so re-running it is safe.

create table if not exists app_state (
     key        text primary key,
     value      jsonb not null,
     updated_at timestamptz not null default now()
   );

create table if not exists users (
     id                text primary key,
     student_id        text,
     email             text not null,
     name              text not null,
     password_hash     text not null,
     role              text not null default 'student' check (role in ('student', 'owner')),
     owner             boolean not null default false,
     suspended         boolean not null default false,
     subscription      jsonb not null,
     usage             jsonb not null,
     lifetime_minutes  integer not null default 0,
     progress          jsonb not null default '{}'::jsonb,
     purchases         jsonb not null default '[]'::jsonb,
     certificates      jsonb not null default '[]'::jsonb,
     invoices          jsonb not null default '[]'::jsonb,
     activity_log      jsonb not null default '[]'::jsonb,
     payment_method    jsonb not null,
     profile           jsonb not null,
     avatar            jsonb,
     last_seen_at      timestamptz,
     created_at        timestamptz not null default now(),
     updated_at        timestamptz not null default now()
   );

create unique index if not exists users_email_key on users (lower(email));

create unique index if not exists users_single_owner on users (owner) where owner;

create index if not exists users_created_at_idx on users (created_at desc);

create sequence if not exists invoice_number_seq start 1007;

create table if not exists payments (
     reference         text primary key,
     user_id           text not null references users(id) on delete cascade,
     kind              text not null check (kind in ('pass', 'course', 'lesson', 'program')),
     period            text check (period in ('daily', 'weekly', 'monthly')),
     course_id         text,
     lesson_id         text,
     program_id        text,
     amount            integer not null check (amount >= 0),
     currency          text not null default 'GHS',
     description       text not null,
     status            text not null default 'pending'
                       check (status in ('pending', 'paid', 'failed', 'abandoned')),
     provider          text not null default 'demo'
                       check (provider in ('demo', 'paystack')),
     phone             text,
     network           text,
     authorization_url text,
     channel           text,
     invoice_number    text,
     provider_event_id text,
     promo_code        text,
     paid_at           timestamptz,
     deposit           boolean not null default false,
     balance_due       integer not null default 0 check (balance_due >= 0),
     settles_reference text references payments(reference),
     created_at        timestamptz not null default now(),
     updated_at        timestamptz not null default now()
   );

create table if not exists promo_codes (
     id                text primary key,
     code              text not null,
     reward_program_id text not null,
     description       text not null default '',
     starts_at         timestamptz not null,
     ends_at           timestamptz not null,
     max_redemptions   integer not null default 0 check (max_redemptions >= 0),
     active            boolean not null default true,
     created_at        timestamptz not null default now(),
     updated_at        timestamptz not null default now()
   );

create unique index if not exists promo_codes_code_key on promo_codes (code);

create index if not exists promo_codes_window_idx on promo_codes (starts_at, ends_at);

create table if not exists promo_redemptions (
     id                text primary key,
     promo_id          text not null,
     code              text not null,
     user_id           text not null,
     payment_reference text not null,
     program_id        text not null,
     value             integer not null default 0,
     created_at        timestamptz not null default now()
   );

create unique index if not exists promo_redemptions_once_key on promo_redemptions (promo_id, user_id);

create unique index if not exists promo_redemptions_payment_key on promo_redemptions (payment_reference);

create index if not exists promo_redemptions_user_idx on promo_redemptions (user_id, created_at desc);

