do $heal$
declare
  payment_user_attnum smallint;
  users_id_attnum smallint;
  payment_reference_attnum smallint;
  payment_settles_attnum smallint;
  keep_user_fk boolean := false;
  keep_settles_fk boolean := false;
  attached_key record;
begin
  select attnum into payment_user_attnum
    from pg_attribute
   where attrelid = 'payments'::regclass
     and attname = 'user_id'
     and not attisdropped;
  select attnum into users_id_attnum
    from pg_attribute
   where attrelid = 'users'::regclass
     and attname = 'id'
     and not attisdropped;
  select attnum into payment_reference_attnum
    from pg_attribute
   where attrelid = 'payments'::regclass
     and attname = 'reference'
     and not attisdropped;
  select attnum into payment_settles_attnum
    from pg_attribute
   where attrelid = 'payments'::regclass
     and attname = 'settles_reference'
     and not attisdropped;

  for attached_key in
    select conname, conkey, confrelid, confkey
      from pg_constraint
     where conrelid = 'payments'::regclass
       and contype = 'f'
  loop
    if payment_user_attnum is not null
       and users_id_attnum is not null
       and attached_key.conkey = array[payment_user_attnum]::smallint[]
       and attached_key.confrelid = 'users'::regclass
       and attached_key.confkey = array[users_id_attnum]::smallint[] then
      keep_user_fk := true;
    elsif payment_settles_attnum is not null
       and payment_reference_attnum is not null
       and attached_key.conkey = array[payment_settles_attnum]::smallint[]
       and attached_key.confrelid = 'payments'::regclass
       and attached_key.confkey = array[payment_reference_attnum]::smallint[] then
      keep_settles_fk := true;
    else
      begin
        execute format('alter table payments drop constraint %I', attached_key.conname);
        raise warning '[codemasterghana] dropped stale payments foreign key % (only payments.user_id -> users.id is supported)', attached_key.conname;
      exception when others then
        raise warning '[codemasterghana] could not drop stale payments foreign key %: %', attached_key.conname, sqlerrm;
      end;
    end if;
  end loop;

  if payment_user_attnum is not null and users_id_attnum is not null and not keep_user_fk then
    begin
      execute 'alter table payments add constraint payments_user_id_fkey foreign key (user_id) references users(id) on delete cascade not valid';
      raise notice '[codemasterghana] added payments.user_id -> users.id foreign key (not validated for legacy rows)';
    exception when others then
      raise warning '[codemasterghana] could not add payments.user_id -> users.id foreign key: %', sqlerrm;
    end;
  end if;

  if payment_settles_attnum is not null and payment_reference_attnum is not null and not keep_settles_fk then
    begin
      execute 'alter table payments add constraint payments_settles_reference_fkey foreign key (settles_reference) references payments(reference) not valid';
      raise notice '[codemasterghana] added payments.settles_reference -> payments.reference foreign key (not validated for legacy rows)';
    exception when others then
      raise warning '[codemasterghana] could not add payments.settles_reference -> payments.reference foreign key: %', sqlerrm;
    end;
  end if;
exception when others then
  raise warning '[codemasterghana] payments foreign key cleanup skipped: %', sqlerrm;
end $heal$;

do $heal$
declare
  stale_rule record;
  wanted_rule record;
begin
  -- One guard around the whole pass: if anything here fails (a table whose
  -- catalogue entry cannot even be read), the app still starts, and the
  -- warning says which constraint was being handled.
  begin
  for stale_rule in
    select conname
      from pg_constraint
     where conrelid = 'payments'::regclass
       and contype = 'c'
       and conname <> 'payments_kind_check'
       and pg_get_constraintdef(oid) ~* '\y(kind|status|provider|period|amount|currency)\y'
  loop
    begin
      execute format('alter table payments drop constraint %I', stale_rule.conname);
      raise warning '[codemasterghana] dropped stale payments rule %', stale_rule.conname;
    exception when others then
      raise warning '[codemasterghana] could not drop payments rule %: %', stale_rule.conname, sqlerrm;
    end;
  end loop;

  for wanted_rule in
    select * from (values
      ('payments_status_check',   $rule$status is null or status in ('pending', 'paid', 'failed', 'abandoned')$rule$),
      ('payments_provider_check', $rule$provider is null or provider in ('demo', 'paystack')$rule$),
      ('payments_period_check',   $rule$period is null or period in ('daily', 'weekly', 'monthly')$rule$),
      ('payments_amount_check',   $rule$amount is null or amount >= 0$rule$),
      ('payments_currency_check', $rule$currency is null or currency = 'GHS'$rule$)
    ) as rules(name, definition)
  loop
    begin
      execute format('alter table payments add constraint %I check (%s) not valid', wanted_rule.name, wanted_rule.definition);
    exception when others then
      raise warning '[codemasterghana] could not add payments rule %: %', wanted_rule.name, sqlerrm;
    end;
  end loop;
  exception when others then
    raise warning '[codemasterghana] payments rule cleanup skipped: %', sqlerrm;
  end;
end $heal$;

do $$
declare
  legacy_column record;
begin
  for legacy_column in
    select column_name
      from information_schema.columns
     where table_schema = current_schema()
       and table_name = 'payments'
       and is_nullable = 'NO'
       and column_default is null
       and column_name not in ('reference', 'user_id', 'kind', 'period', 'course_id', 'lesson_id',
                               'program_id', 'amount', 'currency', 'description', 'status', 'provider',
                               'phone', 'network', 'authorization_url', 'channel', 'invoice_number',
                               'provider_event_id', 'promo_code', 'paid_at', 'created_at', 'updated_at')
       and column_name not in (
         select attribute.attname
           from pg_index index_definition
           join pg_attribute attribute
             on attribute.attrelid = index_definition.indrelid
            and attribute.attnum = any(index_definition.indkey)
          where index_definition.indrelid = 'payments'::regclass
            and (index_definition.indisprimary or index_definition.indisunique)
       )
  loop
    begin
      execute format('alter table payments alter column %I drop not null', legacy_column.column_name);
      raise warning '[codemasterghana] dropped NOT NULL on legacy payments column % (this app never fills it)', legacy_column.column_name;
    exception when others then
      raise warning '[codemasterghana] could not drop NOT NULL on payments.%: %', legacy_column.column_name, sqlerrm;
    end;
  end loop;
end $$;

